        ['03-27', 'Welttheatertag', 'Der Tag wirbt für die Bedeutung des Theaters und wird mit einer internationalen Botschaft begangen. Er wurde 1961 vom Internationalen Theaterinstitut eingeführt.', 'Internationales Theaterinstitut (ITI)'],
        ['03-30', 'Internationaler Tag der Nullverschwendung', 'Der Tag wirbt für Abfallvermeidung und nachhaltige Konsum- und Produktionsmuster. Er wurde 2022 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['03-31', 'Internationaler Tag der Transgender-Sichtbarkeit', 'Der Tag soll die Sichtbarkeit von trans Personen erhöhen und auf Diskriminierung hinweisen. Er geht auf eine Initiative der US-Amerikanerin Rachel Crandall aus dem Jahr 2009 zurück.', 'Initiative von Rachel Crandall, Transgender Michigan'],
        ['03-31', 'Weltbackuptag', 'Der Tag erinnert daran, Datensicherungen regelmäßig anzulegen und zu prüfen. Er geht auf eine Internetinitiative aus dem Jahr 2011 zurück.', 'Initiative World Backup Day'],

        // April
        ['04-01', 'Tag des Aprilscherzes', 'Am 1. April ist es in vielen Ländern Brauch, andere mit erfundenen Nachrichten hereinzulegen. Der Tag geht nicht auf einen offiziellen Beschluss zurück, sondern auf eine seit Jahrhunderten belegte Tradition.', 'Volksbrauch, kein offizieller Herausgeber'],
        ['04-02', 'Internationaler Kinderbuchtag', 'Der Tag wirbt für Kinder- und Jugendliteratur und für das Lesen. Das Datum ist der Geburtstag von Hans Christian Andersen.', 'International Board on Books for Young People (IBBY)'],
        ['04-02', 'Welt-Autismus-Tag', 'Der Tag soll das Verständnis für Menschen im Autismus-Spektrum und ihre Teilhabe fördern. Die Generalversammlung der Vereinten Nationen hat ihn 2007 für den 2. April ausgerufen.', 'Vereinte Nationen'],
        ['04-04', 'Internationaler Tag für Aufklärung über Minengefahr', 'Der Tag erinnert an die Gefahren durch Landminen und explosive Kriegsrückstände und an die Arbeit der Minenräumung. Er wurde von den Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['04-05', 'Internationaler Tag des Gewissens', 'Der Tag ruft dazu auf, das eigene Handeln an Frieden, Toleranz und Verantwortung auszurichten. Die Generalversammlung der Vereinten Nationen hat ihn 2019 beschlossen.', 'Vereinte Nationen'],
        ['04-06', 'Internationaler Tag des Sports für Entwicklung und Frieden', 'Der Tag hebt die Rolle des Sports für gesellschaftlichen Zusammenhalt, Bildung und Gesundheit hervor. Er wurde 2013 von den Vereinten Nationen ausgerufen.', 'Vereinte Nationen'],
        ['04-07', 'Internationaler Tag des Gedenkens an den Völkermord in Ruanda', 'Der Tag erinnert an den Beginn des Völkermords in Ruanda im Jahr 1994 und an die Opfer. Er wurde von den Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['04-07', 'Weltgesundheitstag', 'Der Tag erinnert an die Gründung der Weltgesundheitsorganisation im Jahr 1948 und stellt jedes Jahr ein Gesundheitsthema in den Mittelpunkt.', 'Weltgesundheitsorganisation (WHO)'],
        ['04-08', 'Internationaler Roma-Tag', 'Der Tag macht auf die Kultur der Roma und auf ihre Diskriminierung aufmerksam. Das Datum geht auf den ersten Welt-Roma-Kongress im Jahr 1971 zurück.', 'Internationale Roma-Union'],
        ['04-10', 'Tag der Geschwister', 'Der Tag stellt die Beziehung zwischen Geschwistern in den Mittelpunkt. Er stammt aus den Vereinigten Staaten und wird auf eine private Initiative zurückgeführt.', 'Siblings Day Foundation (USA)'],
        ['04-11', 'Welt-Parkinson-Tag', 'Der Tag informiert über die Parkinson-Krankheit und die Situation der Betroffenen. Das Datum ist der Geburtstag des Arztes James Parkinson.', 'European Parkinson\'s Disease Association'],
        ['04-12', 'Internationaler Tag der bemannten Raumfahrt', 'Der Tag erinnert an den ersten Raumflug eines Menschen durch Juri Gagarin am 12. April 1961. Die Vereinten Nationen haben ihn 2011 ausgerufen.', 'Vereinte Nationen'],
        ['04-14', 'Weltquantentag', 'Der Tag macht auf Quantenphysik und Quantentechnologien aufmerksam. Das Datum spielt auf den Zahlenwert des Planckschen Wirkungsquantums an.', 'internationale Initiative von Quantenforschenden'],
        ['04-15', 'Weltkunsttag', 'Der Tag wirbt für die Bedeutung der bildenden Kunst und der künstlerischen Freiheit. Das Datum ist der Geburtstag von Leonardo da Vinci.', 'UNESCO, initiiert von der International Association of Art'],
        ['04-16', 'Weltstimmtag', 'Der Tag weist auf die Bedeutung der menschlichen Stimme und auf Stimmgesundheit hin. Getragen wird er von Fachgesellschaften aus Medizin, Logopädie und Gesang.', 'Fachverbände für Stimme und Logopädie, Ursprung Brasilien'],
        ['04-17', 'Welt-Hämophilie-Tag', 'Der Tag informiert über Hämophilie und andere angeborene Blutungsstörungen. Das Datum ist der Geburtstag des Verbandsgründers Frank Schnabel.', 'World Federation of Hemophilia'],
        ['04-18', 'Internationaler Denkmaltag', 'Der Tag richtet die Aufmerksamkeit auf Erhalt und Schutz von Denkmälern und historischen Stätten. Er wurde von ICOMOS eingeführt und von der UNESCO bestätigt.', 'ICOMOS'],
        ['04-19', 'Weltlebertag', 'Aktionstag zur Aufklärung über Lebererkrankungen, deren Früherkennung und Vorbeugung. Getragen wird er von hepatologischen Fachgesellschaften und Patientenorganisationen.', 'Hepatologische Fachgesellschaften und Patientenorganisationen (World Liver Day)'],
        ['04-20', 'Tag der chinesischen Sprache', 'Einer der Sprachentage der Vereinten Nationen, der die kulturelle Vielfalt und die Mehrsprachigkeit in der Organisation fördert.', 'Vereinte Nationen'],
        ['04-21', 'Welttag der Kreativität und Innovation', 'Der Tag hebt die Rolle von Kreativität und Innovation für wirtschaftliche und gesellschaftliche Entwicklung hervor. Die Vereinten Nationen haben ihn 2017 beschlossen.', 'Vereinte Nationen'],
        ['04-22', 'Internationaler Tag der Mutter Erde', 'Der Tag ruft zu einem verantwortungsvollen Umgang mit den natürlichen Ressourcen auf. Er wird auch als Earth Day bezeichnet und wurde 2009 von den Vereinten Nationen ausgerufen.', 'Vereinte Nationen'],
        ['04-23', 'Tag des deutschen Bieres', 'Der Tag erinnert an das Reinheitsgebot von 1516. Er wird in Deutschland von der Brauwirtschaft ausgerichtet.', 'Deutscher Brauer-Bund'],
        ['04-23', 'Welttag des Buches und des Urheberrechts', 'Der Tag wirbt für das Lesen, für Bücher und für den Schutz geistigen Eigentums. Er wurde 1995 von der UNESCO eingeführt.', 'UNESCO'],
        ['04-24', 'Internationaler Tag des Multilateralismus und der Diplomatie für den Frieden', 'Der Tag betont die Bedeutung internationaler Zusammenarbeit und friedlicher Streitbeilegung. Er wurde 2018 von den Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['04-24', 'Internationaler Tag des Versuchstiers', 'Der Tag richtet die Aufmerksamkeit auf Tierversuche und auf Alternativmethoden in der Forschung. Er geht auf eine Initiative von Tierschutzorganisationen aus Großbritannien zurück.', 'Tierschutzorganisationen, Ursprung Großbritannien'],
        ['04-25', 'Tag des Baumes', 'In Deutschland wird der Tag des Baumes seit 1952 am 25. April begangen. Er wirbt für Waldschutz und für Baumpflanzungen und wird von der Schutzgemeinschaft Deutscher Wald getragen.', 'Schutzgemeinschaft Deutscher Wald'],
        ['04-25', 'Welt-Malaria-Tag', 'Der Tag informiert über Malaria sowie über Vorbeugung und Behandlung. Er wurde 2007 von der Weltgesundheitsorganisation eingeführt.', 'Weltgesundheitsorganisation (WHO)'],
        ['04-26', 'Internationaler Tag der Erinnerung an die Nuklearkatastrophe von Tschernobyl', 'Der Tag erinnert an den Reaktorunfall von Tschernobyl im Jahr 1986 und an seine Folgen. Die Vereinten Nationen haben ihn 2016 ausgerufen.', 'Vereinte Nationen'],
        ['04-26', 'Welttag des geistigen Eigentums', 'Der Tag informiert über Patente, Marken, Urheberrechte und deren wirtschaftliche Bedeutung. Das Datum erinnert an das Inkrafttreten des WIPO-Übereinkommens im Jahr 1970.', 'Weltorganisation für geistiges Eigentum (WIPO)'],
        ['04-27', 'Welttapirtag', 'Aktionstag, der auf Tapire und den Schutz ihrer Lebensräume aufmerksam macht. Beteiligt sind Artenschutzinitiativen und zoologische Gärten.', 'World Tapir Day, Initiative von Artenschutzorganisationen und Zoos'],
        ['04-28', 'Welttag für Sicherheit und Gesundheit am Arbeitsplatz', 'Der Tag wirbt für Arbeitsschutz und Prävention von Arbeitsunfällen und Berufskrankheiten. Er wurde von der Internationalen Arbeitsorganisation eingeführt.', 'Internationale Arbeitsorganisation (ILO)'],
        ['04-29', 'Internationaler Tag des Tanzes', 'Der Tag würdigt den Tanz in allen Formen. Das Datum ist der Geburtstag des Tanzreformers Jean-Georges Noverre.', 'Internationales Theaterinstitut (ITI)'],
        ['04-29', 'Tag der Erinnerung an alle Opfer chemischer Kriegsführung', 'Der Gedenktag erinnert an die Opfer des Einsatzes chemischer Waffen. Das Datum bezieht sich auf das Inkrafttreten des Chemiewaffenübereinkommens im Jahr 1997.', 'Vereinte Nationen und Organisation für das Verbot chemischer Waffen (OPCW)'],
        ['04-30', 'Internationaler Tag des Jazz', 'Der Tag würdigt den Jazz als Musikform und als Mittel des interkulturellen Dialogs. Die UNESCO hat ihn 2011 ausgerufen.', 'UNESCO'],

        // Mai
        ['05-01', 'Tag der Arbeit', 'Internationaler Tag der Arbeit, der an die Arbeiterbewegung und ihre Forderungen erinnert. In Deutschland gesetzlicher Feiertag in allen Bundesländern.', 'Gesetzlicher Feiertag in Deutschland, Ursprung in der internationalen Arbeiterbewegung'],
        ['05-02', 'Welttag des Thunfischs', 'Der Tag weist auf die Bedeutung des Thunfischs für Ernährung und Beschäftigung sowie auf nachhaltige Fischerei hin. Er wurde von der Generalversammlung der Vereinten Nationen beschlossen und wird seit 2017 begangen.', 'Vereinte Nationen'],
        ['05-03', 'Internationaler Tag der Pressefreiheit', 'Der Tag erinnert an die Bedeutung freier und unabhängiger Medien und an die Lage bedrohter Journalisten. Er geht auf einen Beschluss der UN-Generalversammlung von 1993 zurück und wird seit 1994 begangen.', 'Vereinte Nationen, UNESCO'],
        ['05-04', 'Internationaler Tag der Feuerwehrleute', 'Der Tag ehrt Feuerwehrleute weltweit und erinnert an im Einsatz getötete Kräfte. Das Datum knüpft an den Gedenktag des heiligen Florian an, den Schutzpatron der Feuerwehr.', 'Initiative internationaler Feuerwehrverbände, seit 1999'],
        ['05-04', 'Star-Wars-Tag', 'Inoffizieller Aktionstag der Fangemeinde der Star-Wars-Filme, getragen vom Wortspiel "May the Fourth be with you". Er wird international mit Filmvorführungen und Aktionen begangen.', 'Fangemeinde, breit dokumentierter unoffizieller Aktionstag'],
        ['05-05', 'Europäischer Protesttag zur Gleichstellung von Menschen mit Behinderung', 'Aktionstag für Barrierefreiheit, Teilhabe und Gleichstellung von Menschen mit Behinderung. In Deutschland wird er von Verbänden der Behindertenselbsthilfe und der Aktion Mensch getragen.', 'Verbände der Behindertenselbsthilfe und Aktion Mensch, seit 1992'],
        ['05-05', 'Welthändehygienetag', 'Aktionstag der Weltgesundheitsorganisation für Händehygiene im Gesundheitswesen zur Vermeidung von Infektionen. Er wird im Rahmen der Kampagne "SAVE LIVES: Clean Your Hands" begangen.', 'Weltgesundheitsorganisation (WHO)'],
        ['05-06', 'Internationaler Anti-Diät-Tag', 'Der Tag richtet sich gegen Schlankheitsdruck und Diätkultur und wirbt für einen unbefangenen Umgang mit dem eigenen Körper. Er geht auf eine Initiative der britischen Aktivistin Mary Evans Young zurück.', 'Initiative von Mary Evans Young (Diet Breakers), seit 1992'],
        ['05-08', 'Tag der Befreiung', 'Gedenktag an das Ende des Zweiten Weltkriegs in Europa am 08.05.1945. In Deutschland ist er kein bundesweiter Feiertag, wird aber mit Gedenkveranstaltungen begangen.', 'Historischer Gedenktag zum Kriegsende 1945'],
        ['05-08', 'Weltrotkreuz- und Rothalbmondtag', 'Der Tag erinnert an die Grundsätze der internationalen Rotkreuz- und Rothalbmondbewegung. Das Datum ist der Geburtstag des Gründers Henry Dunant, geboren am 08.05.1828.', 'Internationale Rotkreuz- und Rothalbmondbewegung'],
        ['05-09', 'Europatag', 'Der Europatag der Europäischen Union erinnert an die Schuman-Erklärung vom 09.05.1950, den Ausgangspunkt der europäischen Integration. Er wird mit Informationsveranstaltungen und offenen Türen der EU-Institutionen begangen.', 'Europäische Union'],
        ['05-10', 'Tag gegen den Schlaganfall', 'Bundesweiter Aktionstag zur Aufklärung über Warnzeichen, Vorbeugung und Behandlung des Schlaganfalls. Er wurde 1999 von der Stiftung Deutsche Schlaganfall-Hilfe ins Leben gerufen.', 'Stiftung Deutsche Schlaganfall-Hilfe'],
        ['05-12', 'Internationaler ME/CFS-Tag', 'Aufklärungstag für myalgische Enzephalomyelitis und das chronische Fatigue-Syndrom, häufig gemeinsam mit Fibromyalgie und weiteren chronischen Erkrankungen begangen. Er wird seit 1995 international von Patientenorganisationen ausgerichtet.', 'Internationale Patientenorganisationen, seit 1995'],
        ['05-12', 'Internationaler Tag der Pflegenden', 'Der Tag würdigt die Arbeit der Pflegeberufe und macht auf ihre Arbeitsbedingungen aufmerksam. Das Datum ist der Geburtstag von Florence Nightingale, geboren am 12.05.1820.', 'International Council of Nurses (ICN)'],
        ['05-13', 'Welt-Cocktail-Tag', 'Der Tag erinnert an die erste bekannte schriftliche Definition des Begriffs Cocktail vom 13.05.1806 in der Zeitung "The Balance and Columbian Repository". Er wird seit 2006 international in der Barszene begangen.', 'Internationale Barkeeper- und Cocktailszene, seit 2006'],
        ['05-14', 'Tag des Wanderns', 'Deutschlandweiter Aktionstag rund um das Wandern, der auf das Gründungsdatum des Deutschen Wanderverbands zurückgeht. Vereine und Regionen bieten an diesem Tag geführte Touren und Veranstaltungen an.', 'Deutscher Wanderverband'],
        ['05-15', 'Internationaler Tag der Familie', 'Der Tag rückt die Rolle der Familie in Gesellschaft und Politik in den Mittelpunkt. Er wurde von der UN-Generalversammlung beschlossen und wird seit 1994 begangen.', 'Vereinte Nationen'],
        ['05-15', 'Internationaler Tag der Kriegsdienstverweigerung', 'Der Tag erinnert an Menschen, die den Dienst an der Waffe aus Gewissensgründen ablehnen. Er wird seit 1982 von Friedensorganisationen begangen.', 'Internationale Friedensbewegung, seit 1982'],
        ['05-16', 'Internationaler Tag des Lichts', 'Der Tag hebt die Bedeutung von Licht und Lichttechnologien für Wissenschaft, Kultur und Wirtschaft hervor. Das Datum erinnert an den ersten erfolgreichen Betrieb eines Lasers am 16.05.1960.', 'UNESCO'],
        ['05-16', 'Internationaler Tag des friedlichen Zusammenlebens', 'Der Tag wirbt für Verständigung, Toleranz und friedliches Zusammenleben in Vielfalt. Er wurde von der UN-Generalversammlung beschlossen und wird seit 2018 begangen.', 'Vereinte Nationen'],
        ['05-17', 'Internationaler Tag gegen Homophobie, Biphobie und Transphobie', 'Aktionstag gegen Diskriminierung aufgrund sexueller Orientierung und Geschlechtsidentität, kurz IDAHOBIT. Das Datum erinnert an den 17.05.1990, als die Weltgesundheitsorganisation Homosexualität aus ihrem Diagnoseschlüssel für Krankheiten strich.', 'Internationale Initiative von Menschenrechtsorganisationen, seit 2005'],
        ['05-17', 'Welttag der Telekommunikation und der Informationsgesellschaft', 'Der Tag befasst sich mit den Chancen und Risiken von Telekommunikation und digitaler Vernetzung. Das Datum erinnert an die Gründung der Internationalen Fernmeldeunion am 17.05.1865.', 'Internationale Fernmeldeunion (ITU), Sonderorganisation der Vereinten Nationen'],
        ['05-19', 'Welt-CED-Tag', 'Welttag der chronisch entzündlichen Darmerkrankungen Morbus Crohn und Colitis ulcerosa. Er wird seit 2010 von Patientenorganisationen ausgerichtet und soll die Sichtbarkeit der Betroffenen erhöhen.', 'European Federation of Crohn\'s and Ulcerative Colitis Associations (EFCCA) und weitere Patientenorganisationen'],
        ['05-20', 'Weltbienentag', 'Der Tag weist auf die Bedeutung von Bienen und anderen Bestäubern für Ernährung und Artenvielfalt hin. Das Datum ist der Geburtstag des Bienenkundlers Anton Janša.', 'Vereinte Nationen, seit 2018'],
        ['05-20', 'Weltmetrologietag', 'Der Tag befasst sich mit Messwesen, Normung und Einheiten. Er erinnert an die Unterzeichnung der Meterkonvention am 20.05.1875.', 'Internationales Büro für Maß und Gewicht (BIPM) und Internationale Organisation für das gesetzliche Messwesen (OIML)'],
        ['05-21', 'Internationaler Tag des Tees', 'Der Tag befasst sich mit der wirtschaftlichen und kulturellen Bedeutung des Tees sowie mit den Arbeitsbedingungen im Teeanbau. Er wurde von der UN-Generalversammlung beschlossen und wird seit 2020 begangen.', 'Vereinte Nationen, FAO'],
        ['05-21', 'Welttag der kulturellen Vielfalt für Dialog und Entwicklung', 'Der Tag wirbt für kulturelle Vielfalt als Grundlage von Dialog und Entwicklung. Er geht auf einen Beschluss der UN-Generalversammlung von 2002 zurück.', 'Vereinte Nationen, UNESCO'],
        ['05-22', 'Internationaler Tag der biologischen Vielfalt', 'Der Tag macht auf den Verlust von Arten und Lebensräumen aufmerksam. Das Datum erinnert an die Annahme des Übereinkommens über die biologische Vielfalt am 22.05.1992.', 'Vereinte Nationen'],
        ['05-23', 'Tag des Grundgesetzes', 'Gedenktag an die Verkündung des Grundgesetzes für die Bundesrepublik Deutschland am 23.05.1949. Er ist kein gesetzlicher Feiertag, wird aber vielfach für politische Bildungsarbeit genutzt.', 'Gedenktag zur Verkündung des Grundgesetzes 1949'],
        ['05-23', 'Weltschildkrötentag', 'Der Tag weist auf die Bedrohung von Land- und Wasserschildkröten durch Lebensraumverlust und Handel hin. Er wurde von der Tierschutzorganisation American Tortoise Rescue ins Leben gerufen.', 'American Tortoise Rescue, seit 2000'],
        ['05-24', 'Europäischer Tag der Parke', 'Aktionstag für Nationalparke, Naturparke und Biosphärenreservate in Europa. Das Datum erinnert an die Ausweisung der ersten europäischen Nationalparke in Schweden am 24.05.1909.', 'EUROPARC Federation, seit 1999'],
        ['05-25', 'Handtuchtag', 'Gedenktag für den Schriftsteller Douglas Adams, bei dem Anhänger ein Handtuch sichtbar mit sich führen, eine Anspielung auf "Per Anhalter durch die Galaxis". Er wird seit 2001 von der Lesergemeinde begangen.', 'Lesergemeinde von Douglas Adams, seit 2001'],
        ['05-25', 'Weltschilddrüsentag', 'Der Tag informiert über Schilddrüsenerkrankungen, deren Früherkennung und Behandlung. Er wurde 2008 von der European Thyroid Association gemeinsam mit weiteren Fachgesellschaften eingeführt.', 'European Thyroid Association (ETA) und weitere Fachgesellschaften'],
        ['05-28', 'Weltspieltag', 'Aktionstag für das Recht von Kindern auf Spiel und ausreichend Spielräume. In Deutschland wird er vom Deutschen Kinderhilfswerk koordiniert, international geht er auf die International Toy Library Association zurück.', 'International Toy Library Association, in Deutschland Deutsches Kinderhilfswerk'],
        ['05-28', 'Welttag der Menstruationshygiene', 'Der Tag befasst sich mit Menstruationshygiene, Aufklärung und dem Abbau von Tabus. Das Datum verweist auf einen Zyklus von durchschnittlich 28 Tagen und eine Menstruation von etwa fünf Tagen.', 'WASH United, seit 2014'],
        ['05-29', 'Internationaler Tag der Friedenssicherer der Vereinten Nationen', 'Der Tag ehrt die Angehörigen der Friedensmissionen der Vereinten Nationen und erinnert an die im Dienst Getöteten. Er wird seit 2003 begangen.', 'Vereinte Nationen'],
        ['05-29', 'Welttag der Verdauungsgesundheit', 'Der Tag informiert über Vorbeugung und Behandlung von Erkrankungen des Verdauungssystems. Er wird jährlich mit einem wechselnden Schwerpunktthema begangen.', 'World Gastroenterology Organisation (WGO)'],
        ['05-30', 'Internationaler Tag der Kartoffel', 'Der Tag hebt die Bedeutung der Kartoffel für Ernährungssicherung und nachhaltige Landwirtschaft hervor. Die UN-Generalversammlung beschloss ihn im Dezember 2023, erstmals begangen wurde er 2024.', 'Vereinte Nationen, FAO'],
        ['05-30', 'Welt-Multiple-Sklerose-Tag', 'Der Tag macht auf die Erkrankung Multiple Sklerose und die Situation der Betroffenen aufmerksam. Er wird international mit Kampagnen und Informationsangeboten begangen.', 'Multiple Sclerosis International Federation (MSIF)'],
        ['05-31', 'Weltnichtrauchertag', 'Der Tag informiert über die Gesundheitsrisiken des Tabakkonsums und über Wege zum Rauchstopp. Er wird seit 1987 von der Weltgesundheitsorganisation ausgerichtet.', 'Weltgesundheitsorganisation (WHO)'],

        // Juni
        ['06-01', 'Internationaler Kindertag', 'Aktionstag für die Rechte und den Schutz von Kindern, der in Deutschland und in vielen weiteren Ländern am 1. Juni begangen wird. Er ist vom Weltkindertag am 20. September zu unterscheiden.', 'Internationale Demokratische Frauenföderation, seit 1950 begangen'],
        ['06-01', 'Weltmilchtag', 'Tag zur Bedeutung von Milch und Milchprodukten in der Ernährung sowie zur Rolle der Milchwirtschaft. Er wird seit 2001 begangen.', 'Ernährungs- und Landwirtschaftsorganisation der Vereinten Nationen (FAO)'],
        ['06-03', 'Weltfahrradtag', 'Tag zur Förderung des Fahrrads als einfaches, kostengünstiges und umweltfreundliches Verkehrsmittel. Die Generalversammlung der Vereinten Nationen hat ihn 2018 ausgerufen.', 'Vereinte Nationen'],
        ['06-04', 'Internationaler Tag der Kinder, die unschuldige Opfer von Aggression werden', 'Gedenktag für Kinder, die Opfer von Gewalt und bewaffneten Konflikten werden. Er wurde 1982 von der Generalversammlung der Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['06-05', 'Internationaler Tag gegen illegale, ungemeldete und unregulierte Fischerei', 'Tag zur Bekämpfung nicht gemeldeter und unregulierter Fischerei und ihrer Folgen für Fischbestände und Küstenregionen.', 'Vereinte Nationen, Ernährungs- und Landwirtschaftsorganisation (FAO)'],
        ['06-05', 'Weltumwelttag', 'Zentraler Umweltaktionstag der Vereinten Nationen, der seit 1973 jährlich unter einem wechselnden Schwerpunktthema stattfindet. In Deutschland beteiligen sich Kommunen, Verbände und Unternehmen mit eigenen Aktionen.', 'Umweltprogramm der Vereinten Nationen (UNEP)'],
        ['06-06', 'Sehbehindertentag', 'Bundesweiter Aktionstag zur Situation von Menschen mit Sehbehinderung, der seit 1998 jährlich am 6. Juni stattfindet. Er steht jedes Jahr unter einem eigenen Schwerpunktthema.', 'Deutscher Blinden- und Sehbehindertenverband (DBSV)'],
        ['06-07', 'Weltlebensmittelsicherheitstag', 'Tag zur Vermeidung, Erkennung und Behandlung von durch Lebensmittel übertragenen Risiken. Er wird seit 2019 begangen.', 'Vereinte Nationen, Weltgesundheitsorganisation und FAO'],
        ['06-08', 'Welttag der Ozeane', 'Tag zur Bedeutung der Meere für Klima, Ernährung und Wirtschaft sowie zu ihrem Schutz. Die Vereinten Nationen begehen ihn offiziell seit 2009.', 'Vereinte Nationen'],
        ['06-09', 'Internationaler Tag der Archive', 'Tag zur Rolle von Archiven für Verwaltung, Forschung und Rechtssicherheit. Das Datum erinnert an die Gründung des Internationalen Archivrats am 9. Juni 1948.', 'Internationaler Archivrat (ICA)'],
        ['06-10', 'Kindersicherheitstag', 'Bundesweiter Aktionstag zur Vermeidung von Kinderunfällen in Haushalt und Freizeit, der seit dem Jahr 2000 jährlich am 10. Juni stattfindet.', 'Bundesarbeitsgemeinschaft Mehr Sicherheit für Kinder e. V.'],
        ['06-11', 'Internationaler Tag des Spielens', 'Tag zur Bedeutung des Spiels für Entwicklung, Bildung und Wohlbefinden von Kindern. Die Generalversammlung der Vereinten Nationen hat ihn 2024 ausgerufen.', 'Vereinte Nationen'],
        ['06-12', 'Welttag gegen Kinderarbeit', 'Aktionstag gegen ausbeuterische Kinderarbeit, der seit 2002 jährlich begangen wird. Er richtet sich an Politik, Wirtschaft und Lieferketten.', 'Internationale Arbeitsorganisation (ILO)'],
        ['06-13', 'Internationaler Tag des Albinismus', 'Tag zur Aufklärung über Albinismus und gegen die Diskriminierung betroffener Menschen. Er wurde 2014 von den Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['06-14', 'Weltblutspendetag', 'Tag zum Dank an freiwillige Blutspender und zur Bedeutung einer sicheren Blutversorgung. Das Datum erinnert an den Geburtstag von Karl Landsteiner.', 'Weltgesundheitsorganisation (WHO)'],
        ['06-15', 'Tag des Windes', 'Aktionstag der Windenergiebranche zur Bedeutung der Windkraft für die Stromversorgung. Er wird international am 15. Juni begangen.', 'Global Wind Energy Council und WindEurope'],
        ['06-15', 'Welttag gegen die Misshandlung älterer Menschen', 'Tag zur Aufklärung über Gewalt, Vernachlässigung und finanzielle Ausnutzung im Alter. Die Vereinten Nationen haben ihn 2011 offiziell anerkannt.', 'Vereinte Nationen'],
        ['06-16', 'Bloomsday', 'Literarischer Gedenktag zum Roman Ulysses von James Joyce, dessen Handlung am 16. Juni 1904 in Dublin spielt. Er wird mit Lesungen und Rundgängen in Dublin und international begangen.', 'Literarisches Brauchtum in Dublin, bezogen auf James Joyces Roman Ulysses'],
        ['06-16', 'Internationaler Tag der Familienrücküberweisungen', 'Tag zur wirtschaftlichen Bedeutung von Geldüberweisungen von Arbeitsmigranten an ihre Familien. Die Vereinten Nationen haben ihn 2018 anerkannt.', 'Vereinte Nationen, Internationaler Fonds für landwirtschaftliche Entwicklung (IFAD)'],
        ['06-17', 'Gedenktag 17. Juni', 'Nationaler Gedenktag in Deutschland zur Erinnerung an den Volksaufstand in der DDR am 17. Juni 1953. Bis 1990 war das Datum gesetzlicher Feiertag in der Bundesrepublik.', 'Bundesrepublik Deutschland'],
        ['06-17', 'Welttag zur Bekämpfung von Wüstenbildung und Dürre', 'Tag zu Bodendegradation, Dürrefolgen und nachhaltiger Landnutzung. Er wird seit 1995 begangen.', 'Vereinte Nationen'],
        ['06-18', 'Internationaler Tag der nachhaltigen Gastronomie', 'Tag zur Verbindung von Esskultur, regionaler Erzeugung und nachhaltiger Ernährung. Die Vereinten Nationen haben ihn 2016 ausgerufen.', 'Vereinte Nationen'],
        ['06-19', 'Internationaler Tag zur Beseitigung sexueller Gewalt in Konflikten', 'Gedenk- und Aktionstag gegen sexualisierte Gewalt in bewaffneten Konflikten. Er wurde 2015 von den Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['06-19', 'Juneteenth', 'Gedenktag in den Vereinigten Staaten zur Erinnerung an das Ende der Sklaverei in Texas am 19. Juni 1865. Seit 2021 ist er dort Bundesfeiertag.', 'Vereinigte Staaten von Amerika'],
        ['06-20', 'Nationaler Gedenktag für die Opfer von Flucht und Vertreibung', 'Gedenktag in Deutschland für Opfer von Flucht und Vertreibung, den die Bundesregierung auf den 20. Juni gelegt hat.', 'Bundesregierung der Bundesrepublik Deutschland'],
        ['06-20', 'Weltflüchtlingstag', 'Tag für Menschen, die weltweit auf der Flucht sind, begangen seit 2001. Er geht auf einen Beschluss der Generalversammlung der Vereinten Nationen zurück.', 'Vereinte Nationen, UNHCR'],
        ['06-21', 'Fête de la Musique', 'Musikfest am kalendarischen Sommeranfang mit offenen, meist kostenlosen Konzerten im öffentlichen Raum. Es geht auf eine Initiative des französischen Kulturministeriums von 1982 zurück und findet auch in vielen deutschen Städten statt.', 'Frankreich, Kulturministerium'],
        ['06-21', 'Internationaler Tag des Yoga', 'Tag zu Yoga als Übungspraxis für körperliches und seelisches Wohlbefinden. Die Vereinten Nationen haben ihn 2014 beschlossen, erstmals begangen 2015.', 'Vereinte Nationen'],
        ['06-22', 'Welttag des Regenwaldes', 'Aktionstag zum Schutz und zur Wiederherstellung tropischer Regenwälder, begangen seit 2017.', 'Rainforest Partnership'],
        ['06-23', 'Internationaler Olympischer Tag', 'Tag des Sports und der olympischen Idee mit Breitensportaktionen weltweit. Das Datum erinnert an die Gründung des Internationalen Olympischen Komitees am 23. Juni 1894.', 'Internationales Olympisches Komitee (IOC)'],
        ['06-23', 'Tag des öffentlichen Dienstes der Vereinten Nationen', 'Tag zur Anerkennung der Arbeit des öffentlichen Dienstes und guter Verwaltungspraxis. Er wurde 2002 von den Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['06-24', 'Internationaler Tag der Frauen in der Diplomatie', 'Tag zur Beteiligung von Frauen in Diplomatie und Außenpolitik. Die Generalversammlung der Vereinten Nationen hat ihn 2022 ausgerufen.', 'Vereinte Nationen'],
        ['06-24', 'Johannistag', 'Kirchlicher Festtag zur Geburt Johannes des Täufers, der in Deutschland mit vielfältigem Brauchtum verbunden ist. Traditionell endet an diesem Tag die Spargelsaison.', 'Christliches Brauchtum, Fest der Geburt Johannes des Täufers'],
        ['06-25', 'Tag des Seefahrers', 'Tag zur Anerkennung der Arbeit von Seeleuten für den weltweiten Warenverkehr. Er wurde 2010 beschlossen und wird seit 2011 begangen.', 'Internationale Seeschifffahrtsorganisation (IMO)'],
        ['06-25', 'Welt-Vitiligo-Tag', 'Aufklärungstag zur Hautkrankheit Vitiligo und zur Situation der Betroffenen.', 'Initiative internationaler Vitiligo-Patientenorganisationen'],
        ['06-26', 'Internationaler Tag gegen Drogenmissbrauch und unerlaubten Suchtstoffverkehr', 'Tag zur Prävention von Suchtmittelmissbrauch und zur Bekämpfung des illegalen Drogenhandels. Er besteht seit 1987.', 'Vereinte Nationen'],
        ['06-26', 'Internationaler Tag zur Unterstützung der Folteropfer', 'Gedenktag für Opfer von Folter und für das absolute Folterverbot. Das Datum bezieht sich auf das Inkrafttreten der UN-Antifolterkonvention.', 'Vereinte Nationen'],
        ['06-27', 'Internationaler Tag der kleinen und mittleren Unternehmen', 'Tag zur wirtschaftlichen Bedeutung von Kleinst-, kleinen und mittleren Unternehmen für Beschäftigung und Wertschöpfung. Die Vereinten Nationen haben ihn 2017 ausgerufen.', 'Vereinte Nationen'],
        ['06-27', 'Siebenschläfertag', 'Alter Wetterlostag, nach dem die Witterung um diese Zeit den weiteren Sommerverlauf prägen soll. Der Name geht auf die Legende der Sieben Schläfer von Ephesus zurück.', 'Deutsches Wetter- und Kalenderbrauchtum'],
        ['06-29', 'Internationaler Tag der Tropen', 'Tag zu Entwicklungschancen und Herausforderungen der tropischen Regionen. Die Vereinten Nationen haben ihn 2016 eingeführt.', 'Vereinte Nationen'],
        ['06-29', 'Tag der Donau', 'Aktionstag der Donauanrainerstaaten zum Gewässerschutz. Das Datum erinnert an die Unterzeichnung des Donauschutzübereinkommens am 29. Juni 1994.', 'Internationale Kommission zum Schutz der Donau'],
        ['06-30', 'Internationaler Asteroidentag', 'Tag zur Aufklärung über Asteroiden und über Risiken von Einschlägen. Das Datum erinnert an das Tunguska-Ereignis vom 30. Juni 1908.', 'Vereinte Nationen'],
        ['06-30', 'Internationaler Tag des Parlamentarismus', 'Tag zur Rolle von Parlamenten in demokratischen Systemen. Das Datum erinnert an die Gründung der Interparlamentarischen Union im Jahr 1889.', 'Vereinte Nationen'],

        // Juli
        ['07-01', 'Kanada-Tag', 'Nationalfeiertag Kanadas. Er erinnert an den Zusammenschluss der britischen Kolonien zum Dominion Kanada am 01.07.1867.', 'Kanada (staatlicher Feiertag)'],
        ['07-02', 'Welt-UFO-Tag', 'Tag zur Auseinandersetzung mit Berichten über unidentifizierte Flugobjekte. Neben dem 2. Juli wird vereinzelt auch der 24. Juni genannt.', 'World UFO Day Organization'],
        ['07-03', 'Internationaler plastiktütenfreier Tag', 'Aktionstag gegen den Verbrauch von Einweg-Plastiktüten und für wiederverwendbare Alternativen. Er wird seit 2009 begangen.', 'Zero Waste Europe'],
        ['07-04', 'Unabhängigkeitstag der Vereinigten Staaten', 'Nationalfeiertag der USA zum Gedenken an die Unabhängigkeitserklärung vom 04.07.1776.', 'Vereinigte Staaten von Amerika (staatlicher Feiertag)'],
        ['07-05', 'Tag des Bikinis', 'Tag, der an die erste öffentliche Präsentation des Bikinis am 05.07.1946 in Paris erinnert. Ein offizieller Herausgeber ist nicht belegt.', 'Jahrestag der Bikini-Präsentation 1946, in Kalendern breit dokumentiert'],
        ['07-06', 'Internationaler Tag des Kusses', 'Aktionstag rund um den Kuss, der auf eine britische Initiative zurückgeht und international übernommen wurde.', 'Ursprung in Großbritannien, kein offizieller Herausgeber belegt'],
        ['07-07', 'Weltschokoladentag', 'Aktionstag rund um Schokolade, der international am 7. Juli begangen wird. Daneben existieren weitere Schokoladentage an anderen Daten.', 'Ursprung nicht eindeutig dokumentiert, international breit geführt'],
        ['07-11', 'Weltbevölkerungstag', 'Tag zur Bevölkerungsentwicklung und zu Fragen der Familienplanung. Er wurde 1989 auf Anregung des Entwicklungsprogramms der Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['07-14', 'Französischer Nationalfeiertag', 'Nationalfeiertag Frankreichs. Er erinnert an den Sturm auf die Bastille am 14.07.1789 und an das Föderationsfest von 1790.', 'Frankreich (staatlicher Feiertag)'],
        ['07-14', 'Welt-Schimpansen-Tag', 'Aktionstag für den Schutz von Schimpansen, erstmals 2018 begangen. Das Datum verweist auf die Ankunft von Jane Goodall im Gombe-Nationalpark am 14.07.1960.', 'Jane Goodall Institute'],
        ['07-15', 'Welttag der Fähigkeiten junger Menschen', 'Tag für die berufliche Qualifizierung Jugendlicher. Er wurde 2014 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['07-17', 'Welt-Emoji-Tag', 'Tag rund um Emojis, eingeführt 2014. Das Datum entspricht dem Kalenderblatt, das das Kalender-Emoji auf Apple-Geräten zeigt.', 'Emojipedia, Initiative von Jeremy Burge'],
        ['07-17', 'Welttag der internationalen Strafgerichtsbarkeit', 'Tag zur Erinnerung an die Annahme des Römischen Statuts des Internationalen Strafgerichtshofs am 17.07.1998.', 'Vertragsstaatenversammlung des Internationalen Strafgerichtshofs'],
        ['07-18', 'Internationaler Nelson-Mandela-Tag', 'Tag des gesellschaftlichen Engagements zu Ehren von Nelson Mandela, dessen Geburtstag auf den 18. Juli fällt. Er wurde 2009 von den Vereinten Nationen ausgerufen.', 'Vereinte Nationen'],
        ['07-20', 'Internationaler Schachtag', 'Tag des Schachsports zum Jahrestag der Gründung des Weltschachbunds FIDE am 20.07.1924. Die Generalversammlung der Vereinten Nationen anerkannte den Tag 2019.', 'Vereinte Nationen, FIDE'],
        ['07-20', 'Internationaler Tag des Mondes', 'Tag der Mondforschung, 2021 von der Generalversammlung der Vereinten Nationen beschlossen. Das Datum erinnert an die erste Mondlandung am 20.07.1969.', 'Vereinte Nationen'],
        ['07-21', 'Belgischer Nationalfeiertag', 'Nationalfeiertag Belgiens. Er erinnert an den Amtseid von König Leopold I. am 21.07.1831.', 'Belgien (staatlicher Feiertag)'],
        ['07-22', 'Pi-Annäherungstag', 'Tag der Kreiszahl Pi in der europäischen Datumsschreibweise 22.7., abgeleitet aus dem Bruch 22 geteilt durch 7 als Näherungswert.', 'Mathematische Tradition, kein offizieller Herausgeber'],
        ['07-22', 'Welttag des Gehirns', 'Tag für neurologische Gesundheit und Zugang zur Versorgung, seit 2014 begangen. Das Datum ist der Gründungstag der World Federation of Neurology am 22.07.1957.', 'World Federation of Neurology'],
        ['07-24', 'Internationaler Tag der Selbstfürsorge', 'Tag für Eigenverantwortung in Gesundheitsfragen, seit 2011 begangen. Das Datum 24.7. verweist symbolisch auf 24 Stunden an 7 Tagen.', 'International Self-Care Foundation'],
        ['07-25', 'Welttag zur Verhütung des Ertrinkens', 'Tag zur Vermeidung von Ertrinkungsunfällen, 2021 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['07-26', 'Internationaler Tag zur Erhaltung des Mangroven-Ökosystems', 'Tag für den Schutz der Mangrovenwälder, 2015 von der UNESCO ausgerufen. Das Datum wurde zuvor bereits von Küstengemeinden im Südostpazifik begangen.', 'UNESCO'],
        ['07-27', 'Weltkopf-Hals-Krebstag', 'Aktionstag zur Aufklärung über Tumorerkrankungen im Kopf- und Halsbereich sowie über Früherkennung. Er richtet sich an Fachkreise und Öffentlichkeit.', 'International Federation of Head and Neck Oncologic Societies (IFHNOS)'],
        ['07-28', 'Welt-Hepatitis-Tag', 'Tag zur Aufklärung über Virushepatitis. Das Datum ist der Geburtstag von Baruch Blumberg, dem Entdecker des Hepatitis-B-Virus.', 'Weltgesundheitsorganisation (WHO)'],
        ['07-29', 'Internationaler Tag des Tigers', 'Tag für den Schutz wildlebender Tiger. Er geht auf den Tigerschutzgipfel der Tigerstaaten in St. Petersburg im Jahr 2010 zurück.', 'Tigerschutzgipfel St. Petersburg 2010, Tigerstaaten'],
        ['07-30', 'Internationaler Tag der Freundschaft', 'Tag zur Förderung von Freundschaft zwischen Menschen, Ländern und Kulturen, 2011 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['07-30', 'Welttag gegen Menschenhandel', 'Tag gegen Menschenhandel und für den Schutz der Betroffenen, 2013 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['07-31', 'Weltrangertag', 'Tag zur Anerkennung der Arbeit von Rangern in Schutzgebieten und zum Gedenken an im Dienst getötete Ranger. Das Datum ist der Gründungstag der International Ranger Federation im Jahr 1992.', 'International Ranger Federation'],

        // August
        ['08-01', 'Schweizer Bundesfeiertag', 'Nationalfeiertag der Schweiz, der an den Bundesbrief von 1291 erinnert. Er wird seit 1891 begangen und ist seit 1994 landesweit arbeitsfrei.', 'Schweizerische Eidgenossenschaft'],
        ['08-02', 'Europäischer Holocaust-Gedenktag für Sinti und Roma', 'Gedenktag für die im Nationalsozialismus verfolgten und ermordeten Sinti und Roma. Das Europäische Parlament hat ihn 2015 anerkannt, das Datum erinnert an die Ermordung zahlreicher Sinti und Roma im Lager Auschwitz-Birkenau in der Nacht vom 2. auf den 3. August 1944.', 'Europäisches Parlament'],
        ['08-03', 'Tag der Wassermelone', 'Kulinarischer Aktionstag, der die Wassermelone als sommerliches Obst in den Mittelpunkt stellt. Er stammt aus den USA und wird ohne offiziellen Herausgeber begangen.', 'US-amerikanischer Aktionstag (National Watermelon Day), kein offizieller Herausgeber bekannt'],
        ['08-05', 'Internationaler Tag der Verkehrsampel', 'Aktionstag zur Erinnerung an die Inbetriebnahme der ersten elektrischen Verkehrsampel am 5. August 1914 in Cleveland. Er wird ohne offiziellen Herausgeber begangen.', 'Aktionstag zum Jahrestag der ersten elektrischen Verkehrsampel 1914'],
        ['08-06', 'Hiroshima-Gedenktag', 'Gedenktag für die Opfer des Atombombenabwurfs auf Hiroshima am 6. August 1945. Er wird weltweit von Friedensinitiativen mit Mahnwachen und Veranstaltungen begangen.', 'Internationale Friedensbewegung, Jahrestag des Atombombenabwurfs 1945'],
        ['08-07', 'Tag des Leuchtturms', 'Aktionstag zur Bedeutung von Leuchttürmen für die Seefahrt und zu ihrem Erhalt als Baudenkmale. Er stammt aus den USA und bezieht sich auf ein Gesetz zur Bundesverwaltung der Leuchttürme von 1789.', 'US-amerikanischer Aktionstag (National Lighthouse Day)'],
        ['08-08', 'Weltkatzentag', 'Aktionstag für den Schutz und die artgerechte Haltung von Katzen. Er wurde 2002 vom International Fund for Animal Welfare ausgerufen.', 'International Fund for Animal Welfare (IFAW)'],
        ['08-09', 'Internationaler Tag der indigenen Völker', 'Von den Vereinten Nationen ausgerufener Tag für die Rechte und Kulturen indigener Völker. Er geht auf eine Resolution der Generalversammlung von 1994 zurück.', 'Vereinte Nationen'],
        ['08-09', 'Nagasaki-Gedenktag', 'Gedenktag für die Opfer des Atombombenabwurfs auf Nagasaki am 9. August 1945. Er wird von Friedensinitiativen im Zusammenhang mit dem Hiroshima-Gedenktag begangen.', 'Internationale Friedensbewegung, Jahrestag des Atombombenabwurfs 1945'],
        ['08-10', 'Welt-Löwentag', 'Aktionstag für den Schutz freilebender Löwen und ihrer Lebensräume. Er wird seit 2013 von Natur- und Artenschutzorganisationen begangen.', 'Initiative World Lion Day, getragen von Natur- und Artenschutzorganisationen'],
        ['08-11', 'Welttag der Steel Pan', 'Von den Vereinten Nationen ausgerufener Tag zur Würdigung der Steel Pan als Musikinstrument und Kulturgut aus Trinidad und Tobago. Die Generalversammlung hat ihn 2023 beschlossen.', 'Vereinte Nationen'],
        ['08-12', 'Internationaler Tag der Jugend', 'Von den Vereinten Nationen ausgerufener Tag zur Lage junger Menschen und zur Jugendbeteiligung. Er wird seit dem Jahr 2000 begangen.', 'Vereinte Nationen'],
        ['08-12', 'Welt-Elefantentag', 'Aktionstag für den Schutz von afrikanischen und asiatischen Elefanten, insbesondere gegen Wilderei und Lebensraumverlust. Er wird seit 2012 von Artenschutzinitiativen begangen.', 'Initiative World Elephant Day'],
        ['08-13', 'Gedenktag an den Bau der Berliner Mauer', 'Gedenken an den Beginn des Mauerbaus am 13. August 1961 und an die Opfer der deutschen Teilung. In Berlin finden an diesem Tag offizielle Gedenkveranstaltungen statt.', 'Land Berlin, Gedenken an den Mauerbau 1961'],
        ['08-13', 'Internationaler Tag der Linkshänder', 'Aktionstag für die Belange von Linkshändern, etwa bei Werkzeugen, Arbeitsmitteln und im Schulunterricht. Er geht auf eine Initiative von Lefthanders International aus dem Jahr 1976 zurück.', 'Lefthanders International'],
        ['08-15', 'Mariä Himmelfahrt', 'Katholisches Hochfest der Aufnahme Marias in den Himmel. Es ist gesetzlicher Feiertag im Saarland und in Teilen Bayerns.', 'Katholische Kirche, gesetzlicher Feiertag im Saarland und in Teilen Bayerns'],
        ['08-16', 'Tag der Bratwurst', 'Kulinarischer Aktionstag rund um die Bratwurst. Er stammt aus dem englischsprachigen Raum und wird ohne offiziellen Herausgeber begangen.', 'Aktionstag angelsächsischer Herkunft (Bratwurst Day), kein offizieller Herausgeber bekannt'],
        ['08-17', 'Ehrentag der schwarzen Katze', 'Aktionstag für schwarze Katzen, die in Tierheimen seltener vermittelt werden. Er stammt aus dem US-amerikanischen Tierschutz.', 'Aktionstag aus dem US-amerikanischen Tierschutz (Black Cat Appreciation Day)'],
        ['08-19', 'Weltfotografietag', 'Aktionstag zur Fotografie als Handwerk und Ausdrucksform. Das Datum bezieht sich auf die Freigabe des Daguerreotypie-Verfahrens im Jahr 1839.', 'Initiative World Photography Day, Bezug auf die Freigabe des Daguerreotypie-Verfahrens 1839'],
        ['08-19', 'Welttag der humanitären Hilfe', 'Von den Vereinten Nationen ausgerufener Tag zur Würdigung humanitärer Helfer. Das Datum erinnert an den Anschlag auf das UN-Hauptquartier in Bagdad am 19. August 2003.', 'Vereinte Nationen'],
        ['08-20', 'Weltmückentag', 'Aktionstag zur Erinnerung an den Nachweis der Übertragung von Malaria durch Stechmücken durch Ronald Ross im Jahr 1897. Er wird von der London School of Hygiene and Tropical Medicine begangen und dient der Aufklärung über durch Mücken übertragene Krankheiten.', 'London School of Hygiene and Tropical Medicine'],
        ['08-21', 'Internationaler Tag des Gedenkens an die Opfer des Terrorismus', 'Von den Vereinten Nationen ausgerufener Tag zum Gedenken an Opfer terroristischer Anschläge und zur Würdigung ihrer Rechte. Die Generalversammlung hat ihn 2017 beschlossen.', 'Vereinte Nationen'],
        ['08-21', 'Tag der Senioren', 'Aktionstag zur Anerkennung der Leistungen älterer Menschen. Er geht auf eine Proklamation des US-Präsidenten aus dem Jahr 1988 zurück.', 'Proklamation des US-Präsidenten von 1988 (National Senior Citizens Day)'],
        ['08-22', 'Internationaler Tag des Gedenkens an die Opfer von Gewalt aufgrund der Religion oder Weltanschauung', 'Von den Vereinten Nationen ausgerufener Gedenktag für Menschen, die wegen ihrer Religion oder Weltanschauung Opfer von Gewalt geworden sind. Die Generalversammlung hat ihn 2019 beschlossen.', 'Vereinte Nationen'],
        ['08-22', 'Weltpflanzenmilchtag', 'Aktionstag für pflanzliche Milchalternativen und deren Bedeutung für Ernährung und Ressourcenverbrauch. Er wird seit 2017 von einer internationalen Initiative begangen.', 'Initiative World Plant Milk Day'],
        ['08-23', 'Europäischer Tag des Gedenkens an die Opfer von Stalinismus und Nationalsozialismus', 'Gedenktag für die Opfer beider totalitärer Regime in Europa. Das Datum erinnert an den deutsch-sowjetischen Nichtangriffspakt vom 23. August 1939, das Europäische Parlament hat den Tag 2008 vorgeschlagen.', 'Europäisches Parlament'],
        ['08-23', 'Internationaler Tag der Erinnerung an den Sklavenhandel und seine Abschaffung', 'Von der UNESCO ausgerufener Gedenktag für die Opfer des transatlantischen Sklavenhandels. Das Datum verweist auf den Beginn des Sklavenaufstands auf Haiti in der Nacht vom 22. auf den 23. August 1791.', 'UNESCO'],
        ['08-24', 'Tag der Waffel', 'Kulinarischer Aktionstag rund um die Waffel. Er stammt aus den USA und bezieht sich auf ein Patent für ein Waffeleisen aus dem Jahr 1869.', 'US-amerikanischer Aktionstag (National Waffle Day)'],
        ['08-25', 'Tag des Bananensplits', 'Kulinarischer Aktionstag für das Eisdessert Bananensplit. Er stammt aus den USA und wird ohne offiziellen Herausgeber begangen.', 'US-amerikanischer Aktionstag (National Banana Split Day), kein offizieller Herausgeber bekannt'],
        ['08-27', 'Welttag der Seen', 'Von den Vereinten Nationen ausgerufener Tag zum Schutz von Seen als Süßwasser- und Ökosystemreserven. Die Generalversammlung hat ihn 2024 beschlossen.', 'Vereinte Nationen'],
        ['08-29', 'Internationaler Tag gegen Atomtests', 'Von den Vereinten Nationen ausgerufener Tag gegen Nuklearwaffentests. Das Datum erinnert an die Schließung des Testgeländes Semipalatinsk am 29. August 1991, die Generalversammlung hat den Tag 2009 beschlossen.', 'Vereinte Nationen'],
        ['08-30', 'Internationaler Tag der Opfer des Verschwindenlassens', 'Von den Vereinten Nationen ausgerufener Gedenktag für Opfer des erzwungenen Verschwindenlassens und ihre Angehörigen. Die Generalversammlung hat ihn 2010 beschlossen.', 'Vereinte Nationen'],
        ['08-30', 'Internationaler Tag des Walhais', 'Aktionstag für den Schutz des Walhais als gefährdete Art. Er geht auf eine internationale Fachinitiative zum Walhai zurück.', 'Initiative International Whale Shark Day'],
        ['08-31', 'Internationaler Tag der Menschen afrikanischer Abstammung', 'Von den Vereinten Nationen ausgerufener Tag zur Würdigung der Kulturen und Beiträge von Menschen afrikanischer Abstammung und gegen Rassismus. Die Generalversammlung hat ihn 2020 beschlossen, erstmals begangen wurde er 2021.', 'Vereinte Nationen'],

        // September
        ['09-01', 'Antikriegstag', 'Gedenktag zum Beginn des Zweiten Weltkriegs am 1. September 1939, in Deutschland auch als Weltfriedenstag bezeichnet. Der Deutsche Gewerkschaftsbund ruft seit 1957 zu Veranstaltungen an diesem Tag auf.', 'Deutscher Gewerkschaftsbund'],
        ['09-02', 'Weltkokosnusstag', 'Aktionstag zur wirtschaftlichen und ernährungsbezogenen Bedeutung der Kokosnuss. Das Datum erinnert an den Gründungstag der asiatisch-pazifischen Kokosnussgemeinschaft.', 'International Coconut Community, früher Asian and Pacific Coconut Community'],
        ['09-03', 'Tag des Wolkenkratzers', 'Der Tag erinnert an die Architektur und Baugeschichte von Hochhäusern und geht auf den Geburtstag des Architekten Louis Sullivan zurück. Er ist in Listen kurioser Aktionstage breit dokumentiert, wurde aber nicht offiziell ausgerufen.', 'Kein offizieller Herausgeber, breit dokumentierter unoffizieller Aktionstag (Skyscraper Day)'],
        ['09-04', 'Welttag der sexuellen Gesundheit', 'Aktionstag zur Aufklärung über sexuelle Gesundheit und Selbstbestimmung. Er wird seit 2010 jährlich am 4. September begangen.', 'World Association for Sexual Health'],
        ['09-05', 'Internationaler Tag der Wohltätigkeit', 'Von den Vereinten Nationen ausgerufener Tag zur Förderung ehrenamtlichen und wohltätigen Engagements. Das Datum erinnert an den Todestag von Mutter Teresa.', 'Vereinte Nationen'],
        ['09-07', 'Internationaler Tag der sauberen Luft für blauen Himmel', 'Von den Vereinten Nationen ausgerufener Tag zur Verbesserung der Luftqualität. Er wird seit 2020 jährlich am 7. September begangen.', 'Vereinte Nationen'],
        ['09-08', 'Weltalphabetisierungstag', 'Von der UNESCO ausgerufener Tag, der auf Lese- und Schreibkompetenz als Grundlage von Bildung und Teilhabe aufmerksam macht. Er besteht seit 1966.', 'UNESCO'],
        ['09-08', 'Welttag der Physiotherapie', 'Aktionstag zur Bedeutung der Physiotherapie für Gesundheit und Beweglichkeit. Das Datum erinnert an die Gründung des Weltverbands im Jahr 1951.', 'World Physiotherapy'],
        ['09-09', 'Internationaler Tag zum Schutz der Bildung vor Angriffen', 'Von den Vereinten Nationen ausgerufener Tag gegen Angriffe auf Schulen, Lernende und Lehrkräfte in Konfliktgebieten. Er besteht seit 2020.', 'Vereinte Nationen'],
        ['09-09', 'Tag des alkoholgeschädigten Kindes', 'Aktionstag zur Aufklärung über die Folgen von Alkoholkonsum in der Schwangerschaft, auch FASD-Tag genannt. Der neunte Tag des neunten Monats steht symbolisch für die neun Schwangerschaftsmonate.', 'Internationale Initiative zu FASD, in Deutschland FASD Deutschland e. V.'],
        ['09-10', 'Welttag der Suizidprävention', 'Aktionstag zur Vorbeugung von Suiziden und zur Enttabuisierung des Themas. Er wird seit 2003 von der International Association for Suicide Prevention gemeinsam mit der WHO begangen.', 'International Association for Suicide Prevention gemeinsam mit der Weltgesundheitsorganisation'],
        ['09-11', 'Tag der wohnungslosen Menschen', 'Bundesweiter Aktionstag zur Lage wohnungsloser Menschen in Deutschland, auch Tag der Wohnungslosen genannt. Er wird von der Bundesarbeitsgemeinschaft Wohnungslosenhilfe ausgerichtet.', 'Bundesarbeitsgemeinschaft Wohnungslosenhilfe e. V.'],
        ['09-12', 'Internationaler Tag der Süd-Süd-Kooperation', 'Von den Vereinten Nationen ausgerufener Tag zur Zusammenarbeit zwischen Entwicklungs- und Schwellenländern. Das Datum erinnert an die Annahme des Aktionsplans von Buenos Aires im Jahr 1978.', 'Vereinte Nationen'],
        ['09-13', 'Welt-Sepsis-Tag', 'Aktionstag zur früheren Erkennung und Behandlung der Sepsis. Er wird seit 2012 jährlich am 13. September begangen.', 'Global Sepsis Alliance'],
        ['09-15', 'Internationaler Tag der Demokratie', 'Von den Vereinten Nationen ausgerufener Tag zur Stärkung demokratischer Grundsätze und Institutionen. Er besteht seit 2007.', 'Vereinte Nationen'],
        ['09-16', 'Internationaler Tag zur Erhaltung der Ozonschicht', 'Von den Vereinten Nationen ausgerufener Tag zum Schutz der Ozonschicht. Das Datum erinnert an die Unterzeichnung des Montrealer Protokolls im Jahr 1987.', 'Vereinte Nationen'],
        ['09-17', 'Welttag der Patientensicherheit', 'Von der Weltgesundheitsorganisation ausgerufener Tag zur Vermeidung vermeidbarer Schäden in der Gesundheitsversorgung. Er besteht seit 2019.', 'Weltgesundheitsorganisation'],
        ['09-18', 'Internationaler Tag der Lohngleichheit', 'Von den Vereinten Nationen ausgerufener Tag für gleiches Entgelt bei gleicher Arbeit. Er besteht seit 2020.', 'Vereinte Nationen'],
        ['09-19', 'Internationaler Sprich-wie-ein-Pirat-Tag', 'Kurioser Aktionstag, an dem in Piratensprache gesprochen wird. Er entstand 1995 in den USA und ist international verbreitet.', 'Private Initiative aus den USA, kein offizieller Herausgeber'],
        ['09-20', 'Weltkindertag', 'In Deutschland am 20. September begangener Tag für Kinderrechte, mit Aktionen in vielen Städten. Der von den Vereinten Nationen benannte Weltkindertag liegt hingegen am 20. November.', 'Deutsches Kinderhilfswerk und UNICEF Deutschland'],
        ['09-21', 'Internationaler Tag des Friedens', 'Von den Vereinten Nationen ausgerufener Tag für Frieden und Gewaltfreiheit. Seit 2002 liegt er fest auf dem 21. September.', 'Vereinte Nationen'],
        ['09-21', 'Welt-Alzheimertag', 'Aktionstag zur Aufklärung über Demenzerkrankungen und zur Unterstützung von Angehörigen. Er besteht seit 1994.', 'Alzheimer\'s Disease International'],
        ['09-22', 'Europäischer Tag ohne Auto', 'Abschlusstag der Europäischen Mobilitätswoche, der zum Verzicht auf das Auto und zu nachhaltiger Mobilität anregt. Viele Städte richten dazu eigene Aktionen aus.', 'Europäische Kommission, Europäische Mobilitätswoche'],
        ['09-22', 'Welt-Nashorn-Tag', 'Aktionstag zum Schutz der fünf verbliebenen Nashornarten. Er wird seit 2010 jährlich am 22. September begangen.', 'WWF Südafrika'],
        ['09-23', 'Internationaler Tag der Gebärdensprachen', 'Von den Vereinten Nationen ausgerufener Tag zur Anerkennung der Gebärdensprachen. Er besteht seit 2018.', 'Vereinte Nationen'],
        ['09-24', 'Welttag der Gorillas', 'Aktionstag zum Schutz der Gorillas und ihrer Lebensräume. Er wird seit 2017 jährlich am 24. September begangen.', 'Dian Fossey Gorilla Fund'],
        ['09-25', 'Tag der Zahngesundheit', 'Deutscher Aktionstag zur Vorbeugung von Karies und Zahnerkrankungen. Er wird seit 1991 vom Aktionskreis Tag der Zahngesundheit ausgerichtet.', 'Aktionskreis Tag der Zahngesundheit'],
        ['09-25', 'Weltapothekertag', 'Aktionstag zur Rolle der Apotheken in der Gesundheitsversorgung. Das Datum erinnert an die Gründung des Weltapothekerverbands im Jahr 1912.', 'Fédération Internationale Pharmaceutique'],
        ['09-26', 'Europäischer Tag der Sprachen', 'Aktionstag zur sprachlichen Vielfalt in Europa und zum Erlernen von Fremdsprachen. Er wurde 2001 vom Europarat gemeinsam mit der Europäischen Union eingeführt.', 'Europarat'],
        ['09-26', 'Internationaler Tag für die vollständige Beseitigung von Nuklearwaffen', 'Von den Vereinten Nationen ausgerufener Tag für nukleare Abrüstung. Er besteht seit 2014.', 'Vereinte Nationen'],
        ['09-27', 'Welttourismustag', 'Aktionstag zur wirtschaftlichen und kulturellen Bedeutung des Tourismus. Das Datum erinnert an die Annahme der Satzung der Welttourismusorganisation im Jahr 1970.', 'UN Tourism, früher Welttourismusorganisation UNWTO'],
        ['09-28', 'Internationaler Tag für den universellen Zugang zu Informationen', 'Aktionstag für Informationsfreiheit und Transparenz. Er wurde 2015 von der UNESCO eingeführt und 2019 von den Vereinten Nationen bestätigt.', 'UNESCO und Vereinte Nationen'],
        ['09-28', 'Welttollwuttag', 'Aktionstag zur Bekämpfung der Tollwut, insbesondere durch Impfung von Hunden. Das Datum erinnert an den Todestag von Louis Pasteur.', 'Global Alliance for Rabies Control'],
        ['09-29', 'Internationaler Tag des Bewusstseins für Lebensmittelverluste und Lebensmittelverschwendung', 'Von den Vereinten Nationen ausgerufener Tag zur Verringerung von Lebensmittelverlusten entlang der gesamten Wertschöpfungskette. Er besteht seit 2020.', 'Vereinte Nationen, Ernährungs- und Landwirtschaftsorganisation FAO'],
        ['09-29', 'Weltherztag', 'Aktionstag zur Vorbeugung von Herz-Kreislauf-Erkrankungen. Seit 2011 liegt er fest auf dem 29. September.', 'World Heart Federation'],
        ['09-30', 'Internationaler Tag des Übersetzens', 'Aktionstag für Übersetzerinnen, Übersetzer und Dolmetscher, auch Hieronymustag genannt. Die Vereinten Nationen bestätigten den Tag im Jahr 2017.', 'Vereinte Nationen, zuvor Internationaler Übersetzerverband FIT'],

        // Oktober
        ['10-01', 'Internationaler Tag der älteren Menschen', 'Von der UN-Generalversammlung 1990 beschlossener Tag, der auf die Lebenssituation und die Rechte älterer Menschen aufmerksam macht.', 'Vereinte Nationen'],
        ['10-01', 'Weltkaffeetag', 'Seit 2015 einheitlich am 1. Oktober begangener Tag zu Ehren des Kaffees und der Menschen in seiner Wertschöpfungskette.', 'International Coffee Organization'],
        ['10-02', 'Internationaler Tag der Gewaltfreiheit', 'Von den Vereinten Nationen 2007 eingeführter Tag, der auf den Geburtstag von Mahatma Gandhi fällt und für gewaltfreie Konfliktlösung wirbt.', 'Vereinte Nationen'],
        ['10-03', 'Tag der Deutschen Einheit', 'Nationalfeiertag der Bundesrepublik Deutschland zur Erinnerung an die Wiedervereinigung am 3. Oktober 1990, gesetzlicher Feiertag in allen Bundesländern.', 'Bundesrepublik Deutschland, Einigungsvertrag'],
        ['10-04', 'Welttierschutztag', 'Aktionstag für den Schutz der Tiere, angelehnt an den Gedenktag des Franz von Assisi und seit 1931 international begangen.', 'Internationale Tierschutzbewegung, heute World Animal Day'],
        ['10-05', 'Weltlehrertag', 'Seit 1994 von der UNESCO ausgerufener Tag, der die Bedeutung und die Arbeitsbedingungen von Lehrkräften in den Mittelpunkt stellt.', 'UNESCO gemeinsam mit der Internationalen Arbeitsorganisation'],
        ['10-06', 'Internationaler Tag der geologischen Vielfalt', 'Von der UNESCO beschlossener Tag, der die Bedeutung von Gesteinen, Böden, Landschaftsformen und geologischen Prozessen hervorhebt.', 'UNESCO'],
        ['10-06', 'Welttag der Zerebralparese', 'Seit 2012 begangener Tag, der die Situation von Menschen mit Zerebralparese und ihren Angehörigen sichtbar macht.', 'Cerebral Palsy Alliance und United Cerebral Palsy'],
        ['10-07', 'Welt-Baumwolltag', 'Seit 2019 begangener Tag, der die wirtschaftliche Bedeutung der Baumwolle für Erzeugerländer in den Blick nimmt.', 'Welthandelsorganisation, Initiative afrikanischer Baumwollproduzenten'],
        ['10-07', 'Welttag für menschenwürdige Arbeit', 'Seit 2008 vom Internationalen Gewerkschaftsbund ausgerufener Aktionstag für faire Arbeitsbedingungen und Arbeitsrechte.', 'Internationaler Gewerkschaftsbund'],
        ['10-09', 'Weltposttag', 'Erinnert an die Gründung des Weltpostvereins am 9. Oktober 1874 in Bern und an die Rolle der Post im internationalen Austausch.', 'Weltpostverein'],
        ['10-10', 'Welttag der seelischen Gesundheit', 'Seit 1992 begangener Tag, der die Aufmerksamkeit auf psychische Gesundheit und den Zugang zu Hilfsangeboten lenkt.', 'World Federation for Mental Health, unterstützt von der WHO'],
        ['10-11', 'Coming-out-Day', 'Seit 1988 begangener Tag, der Menschen ermutigt, offen zu ihrer sexuellen Orientierung oder Geschlechtsidentität zu stehen.', 'Ursprung in der US-amerikanischen LGBT-Bewegung, heute international übernommen'],
        ['10-11', 'Internationaler Mädchentag', 'Von den Vereinten Nationen 2011 beschlossener Tag, der auf die besonderen Benachteiligungen von Mädchen aufmerksam macht.', 'Vereinte Nationen'],
        ['10-12', 'Welt-Rheuma-Tag', 'Aktionstag zu rheumatischen Erkrankungen, in Deutschland getragen von der Deutschen Rheuma-Liga, international als World Arthritis Day bekannt.', 'Deutsche Rheuma-Liga, international Arthritis and Rheumatism International'],
        ['10-13', 'Internationaler Tag für Katastrophenvorsorge', 'Von den Vereinten Nationen ausgerufener Tag, der Vorsorge und Risikominderung bei Naturkatastrophen thematisiert.', 'Vereinte Nationen'],
        ['10-14', 'Weltnormentag', 'Tag zu Ehren der internationalen Normung, erinnert an die Gründungskonferenz der Normungsarbeit im Jahr 1946.', 'ISO, IEC und ITU'],
        ['10-15', 'Internationaler Tag der Frauen in ländlichen Gebieten', 'Von den Vereinten Nationen 2007 beschlossener Tag, der die Rolle von Frauen in Landwirtschaft und ländlicher Entwicklung würdigt.', 'Vereinte Nationen'],
        ['10-15', 'Welttag des Händewaschens', 'Seit 2008 begangener Tag, der Händewaschen mit Seife als einfache Maßnahme zur Krankheitsvorbeugung bekannt macht.', 'Global Handwashing Partnership'],
        ['10-16', 'Welternährungstag', 'Erinnert an die Gründung der Ernährungs- und Landwirtschaftsorganisation am 16. Oktober 1945 und richtet den Blick auf Hunger und Ernährungssicherung.', 'Ernährungs- und Landwirtschaftsorganisation der Vereinten Nationen'],
        ['10-16', 'Welttag des Brotes', 'Seit 2006 parallel zum Welternährungstag ausgerufener Tag, der Brot als Grundnahrungsmittel und das Bäckerhandwerk würdigt.', 'Internationale Union der Bäcker und Konditoren'],
        ['10-17', 'Internationaler Tag für die Beseitigung der Armut', 'Von den Vereinten Nationen 1992 beschlossener Tag, der auf Armut und soziale Ausgrenzung weltweit aufmerksam macht.', 'Vereinte Nationen'],
        ['10-18', 'Europäischer Tag gegen Menschenhandel', 'Seit 2007 begangener Aktionstag der Europäischen Union zur Bekämpfung des Menschenhandels und zum Schutz der Betroffenen.', 'Europäische Union'],
        ['10-18', 'Welt-Menopause-Tag', 'Aktionstag zur Aufklärung über die Wechseljahre und die damit verbundenen gesundheitlichen Fragen.', 'International Menopause Society'],
        ['10-20', 'Internationaler Tag der Köche', 'Seit 2004 begangener Tag, der die Arbeit der Köchinnen und Köche und das kulinarische Handwerk würdigt.', 'World Association of Chefs Societies'],
        ['10-20', 'Weltosteoporosetag', 'Aktionstag zur Vorbeugung, Erkennung und Behandlung von Osteoporose, seit 1996 begangen.', 'International Osteoporosis Foundation'],
        ['10-22', 'Welttag des Stotterns', 'Seit 1998 begangener Tag, der über Stottern informiert und Vorurteile gegenüber Betroffenen abbauen soll.', 'International Stuttering Association gemeinsam mit weiteren Fachverbänden'],
        ['10-23', 'Internationaler Tag des Schneeleoparden', 'Seit 2013 begangener Tag zum Schutz des Schneeleoparden und seines Lebensraums in den Hochgebirgen Asiens.', 'Erklärung von Bischkek der Verbreitungsstaaten, getragen von Naturschutzorganisationen'],
        ['10-24', 'Tag der Vereinten Nationen', 'Erinnert an das Inkrafttreten der Charta der Vereinten Nationen am 24. Oktober 1945.', 'Vereinte Nationen'],
        ['10-24', 'Weltpoliotag', 'Aktionstag für die weltweite Ausrottung der Kinderlähmung, angelehnt an den Geburtstag des Impfstoffentwicklers Jonas Salk.', 'Rotary International'],
        ['10-25', 'Weltnudeltag', 'Seit 1995 begangener Tag zu Ehren von Pasta und Teigwaren, hervorgegangen aus einem internationalen Branchenkongress in Rom.', 'Internationale Pasta-Organisation, World Pasta Congress'],
        ['10-26', 'Nationalfeiertag der Republik Österreich', 'Staatlicher Feiertag Österreichs zur Erinnerung an den Beschluss des Neutralitätsgesetzes im Jahr 1955.', 'Republik Österreich'],
        ['10-27', 'Welttag des audiovisuellen Erbes', 'Seit 2005 von der UNESCO ausgerufener Tag, der auf die Erhaltung von Film-, Ton- und Videobeständen aufmerksam macht.', 'UNESCO'],
        ['10-28', 'Internationaler Tag der Animation', 'Seit 2002 begangener Tag zu Ehren der Animationskunst, Bezug ist die erste öffentliche Projektion bewegter Bilder durch Émile Reynaud am 28. Oktober 1892.', 'ASIFA, Internationaler Verband des Animationsfilms'],
        ['10-29', 'Welt-Psoriasistag', 'Aktionstag zur Aufklärung über Schuppenflechte und die Versorgungssituation der Betroffenen.', 'International Federation of Psoriasis Associations'],
        ['10-29', 'Weltschlaganfalltag', 'Aktionstag zu Vorbeugung, Erkennung und Behandlung von Schlaganfällen, in Deutschland unter anderem von der Stiftung Deutsche Schlaganfall-Hilfe begleitet.', 'World Stroke Organization'],
        ['10-31', 'Halloween', 'Brauchtumstag am Vorabend von Allerheiligen mit Ursprung in Irland und Schottland, heute international verbreitet.', 'Volksbrauch, keine offizielle Ausrufung'],
        ['10-31', 'Reformationstag', 'Kirchlicher Gedenktag zur Erinnerung an den Thesenanschlag Martin Luthers im Jahr 1517, in mehreren Bundesländern gesetzlicher Feiertag.', 'Evangelische Kirche, gesetzliche Regelung der Bundesländer'],

        // November
        ['11-01', 'Allerheiligen', 'Allerheiligen ist der kirchliche Gedenktag für alle Heiligen. In mehreren Bundesländern ist er gesetzlicher Feiertag.', 'Römisch-katholische Kirche, Feiertagsrecht mehrerer Bundesländer'],
        ['11-01', 'Weltvegantag', 'Der Weltvegantag wirbt für vegane Ernährung und Lebensweise. Er erinnert an die Gründung der britischen Vegan Society im November 1944 und wird seit 1994 begangen.', 'Vegan Society (Großbritannien)'],
        ['11-02', 'Allerseelen', 'Allerseelen ist der kirchliche Gedenktag für alle Verstorbenen. Üblich sind Grabbesuche und Gräbersegnungen.', 'Römisch-katholische Kirche'],
        ['11-02', 'Internationaler Tag zur Beendigung der Straflosigkeit für Verbrechen gegen Journalisten', 'Der Tag richtet die Aufmerksamkeit darauf, dass Gewalt gegen Journalisten häufig unbestraft bleibt. Er wurde von der Generalversammlung der Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['11-03', 'Weltmännertag', 'Der Weltmännertag lenkt die Aufmerksamkeit auf Männergesundheit und Vorsorgeuntersuchungen. Im deutschsprachigen Raum wird er am 3. November begangen, sein Ursprung ist nicht eindeutig belegt.', 'im deutschsprachigen Raum verbreiteter Aktionstag, Herausgeber nicht eindeutig belegt'],
        ['11-05', 'Welttag des Tsunami-Bewusstseins', 'Der Tag soll das Wissen über Tsunamirisiken und Frühwarnsysteme verbreiten. Er wurde 2015 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['11-06', 'Internationaler Tag für die Verhütung der Umweltzerstörung in Kriegen und bewaffneten Konflikten', 'Der Tag weist auf die langfristigen Umweltschäden durch Kriege und bewaffnete Konflikte hin. Er wurde von der Generalversammlung der Vereinten Nationen eingeführt.', 'Vereinte Nationen'],
        ['11-07', 'Internationaler Tag der medizinischen Physik', 'Der Tag würdigt den Beitrag der medizinischen Physik zu Diagnostik und Therapie. Das Datum ist der Geburtstag von Marie Curie, der Tag wird seit 2013 begangen.', 'International Organization for Medical Physics (IOMP)'],
        ['11-08', 'Internationaler Tag der Radiologie', 'Der Tag erinnert an die Entdeckung der Röntgenstrahlen durch Wilhelm Conrad Röntgen am 8. November 1895 und macht die Rolle der Radiologie in der Medizin sichtbar.', 'Europäische Gesellschaft für Radiologie (ESR) gemeinsam mit weiteren radiologischen Fachgesellschaften'],
        ['11-08', 'Weltstadtplanungstag', 'Der Weltstadtplanungstag richtet die Aufmerksamkeit auf Aufgaben und Nutzen der Stadt- und Raumplanung. Er geht auf eine Initiative des argentinischen Stadtplaners Carlos María della Paolera aus dem Jahr 1949 zurück.', 'Initiative von Carlos María della Paolera, getragen von Planerverbänden'],
        ['11-09', 'Gedenktag der Novemberpogrome 1938', 'Am 9. November 1938 begannen die reichsweiten Pogrome gegen die jüdische Bevölkerung. Der Tag wird in Deutschland mit offiziellen Gedenkveranstaltungen begangen.', 'Bund, Länder und Kommunen mit offiziellen Gedenkveranstaltungen'],
        ['11-09', 'Tag des Erfinders', 'Der Tag würdigt Erfinderinnen und Erfinder sowie den Schutz von Ideen. Das Datum ist der Geburtstag der Erfinderin und Schauspielerin Hedy Lamarr, der Tag wird seit 2005 im deutschsprachigen Raum begangen.', 'private Initiative im deutschsprachigen Raum (Tag des Erfinders)'],
        ['11-10', 'Welttag der Wissenschaft für Frieden und Entwicklung', 'Der Tag betont die Bedeutung von Wissenschaft für Gesellschaft, Frieden und nachhaltige Entwicklung. Er wurde von der UNESCO ausgerufen und wird seit 2002 begangen.', 'UNESCO'],
        ['11-11', 'Beginn der Karnevalssession', 'Am 11. November um 11:11 Uhr beginnt in den Karnevalshochburgen die neue Session. Besonders im Rheinland finden dazu öffentliche Auftaktveranstaltungen statt.', 'Karnevalsverbände, insbesondere im Rheinland'],
        ['11-11', 'Martinstag', 'Der Martinstag erinnert an den heiligen Martin von Tours. In Deutschland ist er mit Laternenumzügen und dem Brauch der Martinsgans verbunden.', 'kirchlicher Gedenktag und deutsches Brauchtum'],
        ['11-12', 'Welt-Lungenentzündungstag', 'Der Tag weist auf Lungenentzündung als weltweit häufige Todesursache bei Kindern hin und wirbt für Vorbeugung und Behandlung. Er wird seit 2009 begangen.', 'internationales Bündnis von Gesundheitsorganisationen (Stop Pneumonia)'],
        ['11-13', 'Welttag der Freundlichkeit', 'Der Tag soll zu freundlichem und rücksichtsvollem Verhalten im Alltag anregen. Er wird seit 1998 begangen.', 'World Kindness Movement'],
        ['11-14', 'Weltdiabetestag', 'Der Weltdiabetestag informiert über Diabetes mellitus, Früherkennung und Behandlung. Das Datum ist der Geburtstag von Frederick Banting, einem der Entdecker des Insulins.', 'Internationale Diabetes-Föderation (IDF) und Weltgesundheitsorganisation'],
        ['11-15', 'Tag des inhaftierten Schriftstellers', 'Der Tag erinnert an Schriftstellerinnen und Schriftsteller, die wegen ihrer Arbeit verfolgt oder inhaftiert sind. Er wird seit 1981 begangen.', 'PEN International'],
        ['11-16', 'Internationaler Tag für Toleranz', 'Der Tag wirbt für Toleranz und den Respekt gegenüber kultureller und religiöser Vielfalt. Er wurde auf Initiative der UNESCO eingeführt und wird seit 1996 begangen.', 'Vereinte Nationen und UNESCO'],
        ['11-17', 'Internationaler Studententag', 'Der Tag erinnert an die gewaltsame Schließung der Prager Hochschulen und die Verfolgung tschechischer Studierender im Jahr 1939. Er wird international von Studierendenorganisationen begangen.', 'internationale Studierendenorganisationen, Beschluss von 1941'],
        ['11-17', 'Welt-Frühgeborenen-Tag', 'Der Tag macht auf die Situation zu früh geborener Kinder und ihrer Familien aufmerksam. Er wird international von Elterninitiativen und Fachgesellschaften getragen.', 'European Foundation for the Care of Newborn Infants (EFCNI) und Elternorganisationen'],
        ['11-18', 'Europäischer Antibiotikatag', 'Der Tag informiert über den sachgerechten Einsatz von Antibiotika und über Antibiotikaresistenzen. Er wird seit 2008 begangen.', 'Europäisches Zentrum für die Prävention und die Kontrolle von Krankheiten (ECDC)'],
        ['11-19', 'Internationaler Männertag', 'Der Internationale Männertag befasst sich mit Gesundheit, Rollenbildern und der Rolle von Männern in Familie und Gesellschaft. Er wird seit 1999 begangen.', 'Initiative von Jerome Teelucksingh, University of the West Indies'],
        ['11-19', 'Welttoilettentag', 'Der Welttoilettentag weist darauf hin, dass weltweit viele Menschen keinen Zugang zu sicheren Sanitäranlagen haben. Er ist seit 2013 ein offizieller Tag der Vereinten Nationen.', 'Vereinte Nationen'],
        ['11-20', 'Afrikanischer Industrialisierungstag', 'Der Tag richtet die Aufmerksamkeit auf die industrielle Entwicklung des afrikanischen Kontinents. Er geht auf einen Beschluss der Generalversammlung der Vereinten Nationen zurück.', 'Vereinte Nationen'],
        ['11-20', 'Internationaler Tag der Kinderrechte', 'Der Tag erinnert an die Verabschiedung der UN-Kinderrechtskonvention am 20. November 1989. In Deutschland wird der Weltkindertag zusätzlich am 20. September begangen.', 'Vereinte Nationen'],
        ['11-21', 'Welt-Hallo-Tag', 'Der Welt-Hallo-Tag ruft dazu auf, an diesem Tag mehrere Menschen bewusst zu begrüßen, und wirbt damit für Verständigung. Er geht auf eine private Initiative aus dem Jahr 1973 zurück.', 'private Initiative der Brüder Brian und Michael McCormack'],
        ['11-21', 'Welttag des Fernsehens', 'Der Tag befasst sich mit der Rolle des Fernsehens für Information und Meinungsbildung. Er wurde 1996 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['11-22', 'Cäcilientag', 'Der Cäcilientag ist der Gedenktag der heiligen Cäcilia, der Patronin der Kirchenmusik. Chöre und Musikvereine begehen ihn mit Konzerten und Gottesdiensten.', 'Römisch-katholische Kirche'],
        ['11-22', 'Tag der Hausmusik', 'Der Tag der Hausmusik soll zum gemeinsamen Musizieren im privaten Kreis anregen. Er knüpft an den Cäcilientag an und ist im deutschsprachigen Raum verbreitet.', 'im deutschsprachigen Raum etablierter Aktionstag im Anschluss an den Cäcilientag'],
        ['11-25', 'Internationaler Tag zur Beseitigung von Gewalt gegen Frauen', 'Der Tag richtet die Aufmerksamkeit auf Gewalt gegen Frauen und Mädchen und auf Schutz- und Hilfsangebote. Er wurde 1999 von der Generalversammlung der Vereinten Nationen beschlossen.', 'Vereinte Nationen'],
        ['11-26', 'Welttag des Olivenbaums', 'Der Tag würdigt den Olivenbaum als Kulturpflanze und Symbol für Frieden. Er wurde 2019 von der UNESCO ausgerufen.', 'UNESCO'],
        ['11-26', 'Welttag des nachhaltigen Verkehrswesens', 'Der Tag befasst sich mit sicherer, bezahlbarer und klimaverträglicher Mobilität. Er geht auf einen Beschluss der Generalversammlung der Vereinten Nationen aus dem Jahr 2023 zurück.', 'Vereinte Nationen'],
        ['11-29', 'Internationaler Tag der Solidarität mit dem palästinensischen Volk', 'Der Tag wurde 1977 von der Generalversammlung der Vereinten Nationen eingeführt. Er wird bei den Vereinten Nationen mit Veranstaltungen begangen.', 'Vereinte Nationen'],
        ['11-30', 'Tag der Computersicherheit', 'Der Tag soll an Passwörter, Aktualisierungen und Datensicherungen erinnern und für IT-Sicherheit sensibilisieren. Er wird seit 1988 begangen.', 'unoffizieller Aktionstag aus der IT-Sicherheitsbranche (Computer Security Day)'],
        ['11-30', 'Tag des Gedenkens an alle Opfer chemischer Kriegsführung', 'Der Tag erinnert an die Opfer des Einsatzes chemischer Waffen und wirbt für ein Verbot solcher Waffen. Er wird von der Organisation für das Verbot chemischer Waffen begangen.', 'Organisation für das Verbot chemischer Waffen (OPCW)'],

        // Dezember
        ['12-01', 'Welt-AIDS-Tag', 'Weltweiter Aktionstag zur Aufklärung über HIV und Aids sowie zur Solidarität mit Betroffenen. Er wird seit 1988 begangen.', 'Weltgesundheitsorganisation, Vereinte Nationen'],
        ['12-02', 'Internationaler Tag für die Abschaffung der Sklaverei', 'Der Tag erinnert an die Überwindung von Sklaverei und an heutige Formen von Zwangsarbeit, Menschenhandel und Ausbeutung. Er verweist auf das UN-Übereinkommen von 1949.', 'Vereinte Nationen'],
        ['12-03', 'Internationaler Tag der Menschen mit Behinderungen', 'Der Tag rückt Teilhabe, Barrierefreiheit und gleiche Rechte von Menschen mit Behinderungen in den Mittelpunkt. Er wird seit 1992 begangen.', 'Vereinte Nationen'],
        ['12-04', 'Barbaratag', 'Gedenktag der heiligen Barbara, verbunden mit dem Brauch, Zweige zu schneiden, die zu Weihnachten blühen sollen. Barbara gilt unter anderem als Schutzpatronin der Bergleute.', 'Christliches Brauchtum, katholische Kirche'],
        ['12-04', 'Internationaler Tag der Banken', 'Der Tag würdigt die Rolle von Banken und Entwicklungsbanken bei der Finanzierung nachhaltiger Entwicklung. Er wurde 2019 durch die UN-Generalversammlung ausgerufen.', 'Vereinte Nationen'],
        ['12-05', 'Internationaler Tag des Ehrenamts', 'Der Tag würdigt freiwilliges Engagement und dessen Beitrag zu Gesellschaft und Entwicklung. Er wird seit 1986 begangen.', 'Vereinte Nationen'],
        ['12-05', 'Weltbodentag', 'Der Tag weist auf die Bedeutung fruchtbarer Böden für Ernährung, Wasserhaushalt und Klima hin. Er geht auf eine Initiative der Internationalen Bodenkundlichen Union zurück und wird von der FAO getragen.', 'Vereinte Nationen, Ernährungs- und Landwirtschaftsorganisation FAO'],
        ['12-06', 'Nikolaustag', 'Gedenktag des heiligen Nikolaus von Myra, in Deutschland vor allem als Brauchtumstag für Kinder bekannt. Kein gesetzlicher Feiertag.', 'Christliches Brauchtum, katholische Kirche'],
        ['12-07', 'Internationaler Tag der Zivilluftfahrt', 'Der Tag erinnert an die Unterzeichnung des Abkommens über die Internationale Zivilluftfahrt von 1944 und würdigt die Bedeutung des Luftverkehrs für Wirtschaft und Verständigung.', 'Vereinte Nationen, Internationale Zivilluftfahrtorganisation ICAO'],
        ['12-08', 'Hochfest der Unbefleckten Empfängnis (Mariä Empfängnis)', 'Katholischer Festtag mit festem Datum am 8. Dezember. In Deutschland kein gesetzlicher Feiertag, in Österreich dagegen arbeitsfrei.', 'Katholische Kirche'],
        ['12-09', 'Internationaler Gedenktag für die Opfer von Völkermord und zu seiner Verhütung', 'Der Tag erinnert an die Annahme der Völkermordkonvention am 9. Dezember 1948. Er mahnt Prävention und Schutzverantwortung an.', 'Vereinte Nationen'],
        ['12-09', 'Internationaler Tag gegen Korruption', 'Der Tag begleitet das UN-Übereinkommen gegen Korruption, das am 9. Dezember 2003 zur Unterzeichnung aufgelegt wurde. Er richtet sich an Staaten, Unternehmen und Zivilgesellschaft.', 'Vereinte Nationen'],
        ['12-10', 'Tag der Menschenrechte', 'Der Tag erinnert an die Verkündung der Allgemeinen Erklärung der Menschenrechte am 10. Dezember 1948. Weltweit finden Veranstaltungen und Kampagnen statt.', 'Vereinte Nationen'],
        ['12-11', 'Internationaler Tag der Berge', 'Der Tag weist auf die ökologische und wirtschaftliche Bedeutung von Bergregionen und auf die Lebensbedingungen ihrer Bevölkerung hin. Er wird seit 2003 begangen.', 'Vereinte Nationen'],
        ['12-12', 'Internationaler Tag der Neutralität', 'Der Tag hebt die Rolle staatlicher Neutralität für Konfliktvermeidung und friedliche Streitbeilegung hervor. Er wurde 2017 von der UN-Generalversammlung ausgerufen.', 'Vereinte Nationen'],
        ['12-12', 'Internationaler Tag der allgemeinen Gesundheitsversorgung', 'Der Tag wirbt für einen bezahlbaren Zugang zu Gesundheitsleistungen für alle Menschen. Er wird seit 2017 von den Vereinten Nationen begangen.', 'Vereinte Nationen'],
        ['12-13', 'Luciatag', 'Gedenktag der heiligen Lucia von Syrakus, in Schweden und Skandinavien als Lichterfest mit Umzügen begangen. Fester Termin am 13. Dezember.', 'Christliches Brauchtum, skandinavische Tradition'],
        ['12-14', 'Weltaffentag', 'Aktionstag zur Aufmerksamkeit für Affen und Primaten, im Jahr 2000 von den US-amerikanischen Künstlern Casey Sorrow und Eric Millikin ins Leben gerufen. Er wird seither international von Zoos und Artenschutzorganisationen aufgegriffen.', 'Casey Sorrow und Eric Millikin (Initiatoren, seit 2000)'],
        ['12-15', 'Zamenhof-Tag', 'Gedenktag der Esperanto-Bewegung am Geburtstag von Ludwik Lejzer Zamenhof, dem Initiator der Plansprache Esperanto. Er wird auch als Tag des Esperanto-Buches begangen.', 'Esperanto-Bewegung, unter anderem Universala Esperanto-Asocio'],
        ['12-16', 'Tag der Versöhnung (Südafrika)', 'Gesetzlicher Feiertag in Südafrika, der seit 1995 der nationalen Versöhnung nach dem Ende der Apartheid gewidmet ist. Fester Termin am 16. Dezember.', 'Republik Südafrika'],
        ['12-17', 'Internationaler Tag zur Beendigung der Gewalt gegen Sexarbeiterinnen und Sexarbeiter', 'Aktionstag gegen Gewalt und Stigmatisierung von Menschen in der Sexarbeit, begangen seit 2003. Er geht auf eine Initiative von Selbstorganisationen in den USA zurück.', 'Sex Workers Outreach Project (SWOP)'],
        ['12-18', 'Internationaler Tag der Migranten', 'Der Tag erinnert an die Annahme der UN-Konvention zum Schutz der Rechte von Wanderarbeitnehmern am 18. Dezember 1990. Er thematisiert Rechte und Lebenslagen von Migranten.', 'Vereinte Nationen'],
        ['12-18', 'Welttag der arabischen Sprache', 'Der Tag erinnert daran, dass Arabisch am 18. Dezember 1973 Amtssprache der Vereinten Nationen wurde. Er wird von der UNESCO ausgerichtet.', 'UNESCO'],
        ['12-20', 'Internationaler Tag der menschlichen Solidarität', 'Der Tag stellt Solidarität als Grundwert internationaler Zusammenarbeit und Armutsbekämpfung heraus. Er wurde 2005 von der UN-Generalversammlung ausgerufen.', 'Vereinte Nationen'],
        ['12-21', 'Weltmeditationstag', 'Der Tag verweist auf Meditation als Beitrag zu Gesundheit und innerem Ausgleich. Er wurde von der UN-Generalversammlung im Dezember 2024 auf den 21. Dezember gelegt.', 'Vereinte Nationen'],
        ['12-21', 'Welttag des Basketballs', 'Der Tag erinnert an das erste Basketballspiel am 21. Dezember 1891 und würdigt die soziale Wirkung des Sports. Er wurde 2023 von der UN-Generalversammlung ausgerufen.', 'Vereinte Nationen'],
        ['12-22', 'Nationaler Tag der Mathematik (Indien)', 'In Indien seit 2012 begangener Tag zu Ehren des Geburtstags des Mathematikers Srinivasa Ramanujan. Er dient der Förderung des Interesses an Mathematik in Schulen und Hochschulen.', 'Regierung von Indien (Ausrufung 2012)'],
        ['12-24', 'Heiligabend', 'Vorabend des Weihnachtsfestes mit Bescherung und Christvesper. In Deutschland kein gesetzlicher Feiertag, in vielen Unternehmen jedoch arbeitsfrei oder mit verkürzter Arbeitszeit.', 'Christliche Tradition, allgemeines Brauchtum'],
        ['12-25', 'Erster Weihnachtsfeiertag', 'Hochfest der Geburt Christi und in allen Bundesländern gesetzlicher Feiertag. Fester Termin am 25. Dezember.', 'Feiertagsgesetze der Bundesländer'],
        ['12-26', 'Zweiter Weihnachtsfeiertag (Stephanstag)', 'In allen Bundesländern gesetzlicher Feiertag, kirchlich der Gedenktag des heiligen Stephanus. Fester Termin am 26. Dezember.', 'Feiertagsgesetze der Bundesländer'],
        ['12-27', 'Internationaler Tag der Vorsorge gegen Epidemien', 'Der Tag wirbt für Prävention, Früherkennung und Vorbereitung auf Epidemien. Er wurde 2020 von der UN-Generalversammlung ausgerufen.', 'Vereinte Nationen'],
        ['12-28', 'Fest der Unschuldigen Kinder', 'Kirchlicher Gedenktag für die im Matthäusevangelium beschriebenen getöteten Kinder von Betlehem, im westlichen Kalender am 28. Dezember. Regional bestehen eigene Bräuche.', 'Katholische Kirche'],
        ['12-31', 'Silvester', 'Letzter Tag des Kalenderjahres, benannt nach dem Gedenktag von Papst Silvester I. In Deutschland kein gesetzlicher Feiertag.', 'Allgemeines Brauchtum, christlicher Kalender'],
    ];

    public function run(): void
    {
        foreach (self::EREIGNISSE as [$monatTag, $titel, $beschreibung, $quelle]) {
            DailyFact::updateOrCreate(
                ['month_day' => $monatTag, 'title' => $titel],
                [
                    'description' => $beschreibung,
                    'source' => $quelle,
                    'recurring' => true,
                    'is_active' => true,
                    'specific_date' => null,
                ],
            );
        }
    }
}
